for id,n in pairs(npcs) do P.NPCSources[id]=n end
for key,a in pairs(areas) do P.GatherAreas[key]=a end
for key,a in pairs(nodes) do P.GatherNodeData.areas[key]=a end
for key,a in pairs(zoneareas) do P.GatherZoneAreas[key]=a end
local function append(list,value,seen)
    if value and not seen[value] then list[#list+1]=value;seen[value]=true end
end
for _,entries in pairs(P.GatherAtlas) do
    for _,e in ipairs(entries) do
        local patch=patches[e.item]
        if patch then
            local sources,seen={},{}
            for _,s in ipairs(patch.sources) do
                sources[#sources+1]=s;seen[tostring(s.kind)..":"..tostring(s.id)..":"..s.method]=true
            end
            -- Preserve profession-specific acquisition records as well.
            for _,s in ipairs(e.sources or {}) do
                local key=tostring(s.kind)..":"..tostring(s.id)..":"..s.method
                if s.method~=patch.sourceCoverage.method and not seen[key] then sources[#sources+1]=s;seen[key]=true end
            end
            e.sources=sources;e.sourceCoverage=patch.sourceCoverage
            local mapSeen,refSeen={},{};e.mapKeys={};e.referenceURLs=e.referenceURLs or {}
            for _,url in ipairs(e.referenceURLs) do refSeen[url]=true end
            local words={e.name}
            for _,s in ipairs(sources) do
                words[#words+1]=s.name or "";words[#words+1]=table.concat(s.zones or {}," ")
                for _,key in ipairs(s.mapKeys or {}) do append(e.mapKeys,key,mapSeen) end
                append(e.referenceURLs,s.url,refSeen)
            end
            append(e.referenceURLs,patch.sourceCoverage.url,refSeen)
            e.searchText=string.lower(table.concat(words," "))
            e.sub=(e.sub or "Material"):gsub("%d+ sources",#sources.." sources")
            P.GatherZoneMaps[e.key]=choices[e.item]
        elseif e.item==248824 or e.item==248825 or e.item==249429 then
            e.sourceCoverage={unavailable=true,captured="2026-10-20"}
        end
    end
end
